theorem total_le {fork : Fork} {message : Message fork}
    {state : State.TransactionState} {substate : Substate}
    {bound : Nat} {runChild : MessageRunner fork Nat bound}
    (hfork : .berlin ≤ fork)
    (hsize' : message.data.size < 2 ^ 256)
    (hsep : Sep (callKeys message))
    {gas : Nat} {evm s : Evm fork Nat}
    (start : At CODE message 0 [] .empty gas state substate evm)
    (hrun : EndsL runChild evm s) (hok : s.error = none) :
    (storageAt s.state message.currentTarget 5).toNat ≤
      (storageAt state message.currentTarget 5).toNat

theorem ends_ok_dispatch (hfork : .berlin ≤ fork) (hsize' : message.data.size < 2 ^ 256)
    {gas : Nat} {bound : Nat} {runChild : MessageRunner fork Nat bound} {evm : Evm fork Nat}
    (start : At CODE message 0 [] .empty gas state substate evm) {s : Evm fork Nat}
    (hrun : TokenKit.EndsL runChild evm s) (hok : s.error = none) :
    1 ≤ message.data.size ∧
      ∃ i : Fin 12, selector message.data = ENTRIES[i].1.toNat
